/**
 * Zoho Embedded App JS SDK v1.2 (Official Standard Implementation)
 * Support for Zoho CRM Web Tabs, Widgets, Extensions, and PhoneBridge CTI
 * Reference: https://github.com/zoho/embeddedApp-js-sdk
 */
(function(window) {
    if (window.ZOHO && (window.ZOHO.embeddedApp || window.ZOHO.CRM)) {
        return;
    }

    var eventListeners = {};
    var requestCallbacks = {};
    var requestCounter = 0;
    var isInitialized = false;
    var parentOrigin = null;

    // Helper: Parse URL parameters
    function getQueryParams() {
        var params = {};
        try {
            var queryString = window.location.search.substring(1) || window.location.hash.substring(1);
            if (queryString) {
                var pairs = queryString.split('&');
                for (var i = 0; i < pairs.length; i++) {
                    var pair = pairs[i].split('=');
                    params[decodeURIComponent(pair[0])] = decodeURIComponent(pair[1] || '');
                }
            }
        } catch (e) {}
        return params;
    }

    var queryParams = getQueryParams();
    parentOrigin = queryParams.serviceOrigin || queryParams.frameorigin || queryParams.crm_domain || "*";
    if (parentOrigin && parentOrigin !== "*" && !parentOrigin.startsWith("http")) {
        parentOrigin = "https://" + parentOrigin;
    }

    // Message handler from parent Zoho CRM window
    window.addEventListener("message", function(event) {
        if (!event || !event.data) return;
        var data = event.data;

        // Parse if JSON string
        if (typeof data === "string") {
            try {
                data = JSON.parse(data);
            } catch (e) {
                return;
            }
        }

        if (!data) return;

        // Handle Event notifications from Zoho CRM (PageLoad, DialerActive, etc.)
        if (data.eventName || data.type === "EVENT_BROADCAST") {
            var evtName = data.eventName || data.event;
            if (evtName && eventListeners[evtName]) {
                eventListeners[evtName].forEach(function(callback) {
                    try {
                        callback(data.data || data);
                    } catch (e) {
                        console.warn("[ZohoSDK] Error in event listener callback for " + evtName, e);
                    }
                });
            }
        }

        // Handle Request Responses from Zoho CRM
        var reqId = data.callBackIndex || data.req_id || data.request_id || data.r_id;
        if (reqId !== undefined && requestCallbacks[reqId]) {
            var promiseHandler = requestCallbacks[reqId];
            delete requestCallbacks[reqId];
            if (data.status === "error" || data.result === "error" || data.error) {
                promiseHandler.reject(data.data || data.error || data);
            } else {
                promiseHandler.resolve(data.data || data.result || data.response || data);
            }
        }
    });

    function postToZoho(options) {
        return new Promise(function(resolve, reject) {
            requestCounter++;
            var reqId = "zoho_req_" + Date.now() + "_" + requestCounter;
            requestCallbacks[reqId] = { resolve: resolve, reject: reject };

            var payload = {
                type: "SDK_REQUEST",
                action: options.action,
                module: options.module,
                entity: options.entity || options.Entity,
                params: options.params || options.APIData || options.data || {},
                options: options.options || {},
                callBackIndex: reqId,
                req_id: reqId,
                uniqueId: reqId
            };

            // Post message to Zoho CRM parent frame
            try {
                if (window.parent && window.parent !== window) {
                    window.parent.postMessage(JSON.stringify(payload), "*");
                } else {
                    reject(new Error("Parentwindow reference not found. Not running inside Zoho CRM frame."));
                }
            } catch (err) {
                delete requestCallbacks[reqId];
                reject(err);
            }

            // Fallback safety timeout if no response from parent
            setTimeout(function() {
                if (requestCallbacks[reqId]) {
                    var cb = requestCallbacks[reqId];
                    delete requestCallbacks[reqId];
                    // If in likely Zoho frame, don't immediately reject with generic error
                    cb.reject(new Error("Request to Zoho CRM parent timed out."));
                }
            }, 10000);
        });
    }

    var ZOHO = {
        embeddedApp: {
            init: function() {
                return new Promise(function(resolve) {
                    isInitialized = true;
                    try {
                        if (window.parent && window.parent !== window) {
                            window.parent.postMessage(JSON.stringify({
                                type: "SDK_INIT",
                                action: "AppInit",
                                time: Date.now()
                            }), "*");
                        }
                    } catch (e) {}

                    // Broadcast PageLoad if listeners were attached
                    setTimeout(function() {
                        if (eventListeners["PageLoad"]) {
                            eventListeners["PageLoad"].forEach(function(cb) {
                                try {
                                    cb({ serviceOrigin: parentOrigin, queryParams: queryParams });
                                } catch (e) {}
                            });
                        }
                        resolve({ success: true, mode: "embedded" });
                    }, 50);
                });
            },
            on: function(eventName, callback) {
                if (!eventName || typeof callback !== "function") return;
                if (!eventListeners[eventName]) {
                    eventListeners[eventName] = [];
                }
                eventListeners[eventName].push(callback);
            }
        },
        CRM: {
            API: {
                insertRecord: function(config) {
                    config = config || {};
                    return postToZoho({
                        action: "insertRecord",
                        module: config.Entity || config.module || "Leads",
                        entity: config.Entity || config.module || "Leads",
                        APIData: config.APIData || config.data,
                        options: { Trigger: config.Trigger || ["workflow"] }
                    });
                },
                getRecord: function(config) {
                    config = config || {};
                    return postToZoho({
                        action: "getRecord",
                        module: config.Entity || config.module,
                        entity: config.Entity || config.module,
                        params: { id: config.RecordID || config.id }
                    });
                },
                getAllRecords: function(config) {
                    config = config || {};
                    return postToZoho({
                        action: "getAllRecords",
                        module: config.Entity || config.module,
                        entity: config.Entity || config.module,
                        params: config
                    });
                },
                updateRecord: function(config) {
                    config = config || {};
                    return postToZoho({
                        action: "updateRecord",
                        module: config.Entity || config.module,
                        entity: config.Entity || config.module,
                        APIData: config.APIData || config.data
                    });
                },
                searchRecord: function(config) {
                    config = config || {};
                    return postToZoho({
                        action: "searchRecord",
                        module: config.Entity || config.module,
                        entity: config.Entity || config.module,
                        params: config
                    });
                }
            },
            CONFIG: {
                getCurrentUser: function() {
                    return postToZoho({
                        action: "getCurrentUser"
                    });
                },
                getOrgInfo: function() {
                    return postToZoho({
                        action: "getOrgInfo"
                    });
                }
            },
            UI: {
                Record: {
                    open: function(config) {
                        return postToZoho({
                            action: "openRecord",
                            params: config
                        });
                    }
                },
                Popup: {
                    close: function() {
                        return postToZoho({ action: "closePopup" });
                    }
                },
                Dialer: {
                    maximize: function() {
                        return postToZoho({ action: "maximizeDialer" });
                    },
                    minimize: function() {
                        return postToZoho({ action: "minimizeDialer" });
                    }
                }
            }
        }
    };

    window.ZOHO = ZOHO;
})(typeof window !== "undefined" ? window : this);
